def uc_table(uid):
    name, actors, mod, frs, br = next((u[1], u[2], u[3], u[4], u[5]) for u in D.UCS if u[0] == uid)
    sp = SPEC[uid]
    rows = [['Use Case ID', uid], ['Use Case Name', name], ['Actors', actors], ['Description', sp['desc']], ['Trigger', sp['trigger']], ['Preconditions', sp['pre']], ['Postconditions', sp['post']],
            ['Normal Flow', '\n'.join('%d. %s' % (i + 1, t) for i, t in enumerate(sp['flow']))], ['Alternative Flows', sp['alt']], ['Exceptions', sp['exc']], ['Business Rules', sp['br']], ['Assumptions', sp['ass']]]
    return TBL('uc_' + uid.replace('-', '').lower(), 'Use case specification %s: %s' % (uid, name), ['Field', 'Description'], rows, [1.3, 6.1], fs=17)

def blocks(ctx):
    b = []
    b.append(H1('Appendix A: Use Case List', 'appa', numbered=False))
    b.append(P('{tbl:appa} lists all %d use cases with the module, the requirements and the priority of the module. The use cases are specified in Section {sec:ucspec} (UC-01, UC-02, UC-03, UC-09, UC-23, UC-25) and in Appendix B.' % len(D.UCS)))
    pri = {1: 'High', 2: 'High', 3: 'High', 4: 'High', 5: 'High', 6: 'High', 7: 'Medium', 8: 'Medium', 9: 'Medium', 10: 'Medium', 11: 'Medium', 12: 'High', 13: 'High', 14: 'High', 15: 'High', 16: 'Medium', 17: 'Medium', 18: 'Medium', 19: 'Medium', 20: 'Low', 21: 'Low'}
    rows = []
    for u in D.UCS:
        m = int(u[3][4:]); s = D.UC_SPECS.get(u[0]) or SPEC.get(u[0])
        rows.append([u[0], u[1], u[2], u[3], pri[m], s['desc']])
    b.append(TBL('appa', 'Use case list with descriptions', ['Use Case ID', 'Name', 'Actors', 'Module', 'Priority', 'Description'], rows, [0.7, 1.4, 1.3, 0.7, 0.7, 3.2], fs=15))
    b.append(H1('Appendix B: Detailed Use Case Specifications', 'appb', numbered=False))
    b.append(P('This appendix gives the specifications of the use cases that are not specified in Section {sec:ucspec}, in the same format.'))
    for u in D.UCS:
        if u[0] in SPEC: b.append(uc_table(u[0]))
    b.append(H1('Appendix C: TBD List', 'appc', numbered=False))
    b.append(P('{tbl:tbd} lists the items that depend on a decision or a confirmation outside this specification. Each is stated with the requirement that it affects and with the default that the document uses until the item is resolved.'))
    b.append(TBL('tbd', 'Items to be determined', ['ID', 'Item', 'Affected Requirements', 'Default Used in this Document'], [
        ['TBD-1', 'Confirm the national emergency and helpline numbers (Police 15, Rescue 1122, the missing-child helpline 1099 and the women\'s helplines) and whether each accepts SMS from the public.', 'FR-11.01, FR-17.04, FR-19.04', 'Numbers as listed; SMS is the default channel; call and share are selectable.'],
        ['TBD-2', 'Select the email delivery service and its free tier.', 'FR-01.02, SI-14', 'A transactional email API called from a Cloud Function.'],
        ['TBD-3', 'Confirm the offline keyword spotter against the alternatives with accented speech.', 'FR-03.03, ADR-04', 'The sherpa-onnx keyword spotter.'],
        ['TBD-4', 'Select the open map-data source and renderer and confirm its licence for offline storage.', 'FR-13.02, SI-7, DEP-7', 'OpenStreetMap-derived data with an open-source renderer.'],
        ['TBD-5', 'Confirm the sources and licences of the library content.', 'FR-09.01, AS-9', 'Curated articles from reputable sources, with attribution.'],
        ['TBD-6', 'Tune the algorithm thresholds after calibration on the evaluation data.', 'Table of algorithm parameters', 'The default values of the parameter table.'],
        ['TBD-7', 'Define the identity-check procedure details for helper approval.', 'FR-08.01, FR-16.03', 'Administrator review of an identity document photo.'],
        ['TBD-8', 'Choose the three neutral names and icons of the app disguise.', 'FR-21.01', 'Three neutral appearances, for example Calculator, Notes and Clock.'],
    ], [0.6, 3.2, 1.6, 2.6], fs=16))
    b.append(H1('Appendix D: Sample Test Data', 'appd', numbered=False))
    b.append(P('The following sample data are used to prepare the test cases of Chapter 6. Names, numbers and coordinates are invented.'))
    b.append(TBL('sd_trustee', 'Sample trustees', ['Name', 'Phone', 'Email', 'Channels'], [
        ['Ayesha (sister)', '+92 300 0000001', 'ayesha@example.com', 'SMS, push, email'], ['Bilal (friend)', '+92 300 0000002', '-', 'SMS, WhatsApp'], ['Mother', '+92 300 0000003', '-', 'SMS']], [1.6, 1.6, 2.2, 2.0], fs=17))
    b.append(TBL('sd_sos', 'Sample SOS message', ['Part', 'Content'], [
        ['Template', 'I need help. Please call me.'], ['Added by the system', 'Name: Test User. Location: 33.6844, 73.0479 (fix 4 s old). Time: 17:42. Map: link.'], ['Escalation message', 'Test User needs help. Callback +92 300 0000099. Location 33.6844, 73.0479. Time 17:45. Trigger: voice. Evidence recorded: yes.']], [1.6, 6.0], fs=17))
    b.append(TBL('sd_reports', 'Sample incident reports', ['Category', 'Location (latitude, longitude)', 'Age (days)', 'Expected weight'], [
        ['Harassment', '33.6001, 73.0501', '0', '1.00'], ['Theft', '33.6001, 73.0502', '90', '0.50'], ['Felt unsafe', '33.6002, 73.0501', '180', '0.25']], [1.6, 2.6, 1.2, 1.6], fs=17))
    b.append(TBL('sd_queries', 'Sample library queries', ['Query', 'Expected best item category'], [
        ['help a friend after harassment', 'After-incident care'], ['how can I walk home safely at night', 'Prevention'], ['what do I do if I am followed', 'Emergency response'], ['I feel afraid and alone', 'Emotional support']], [4.0, 3.6], fs=17))
    b.append(TBL('sd_audio', 'Sample audio test set (labelled clips)', ['Label', 'Examples', 'Minimum clips'], [
        ['Distress', 'Scream, shout for help, cry of fear', '50'], ['Non-distress loud', 'Door slam, applause, traffic horn, cheering, dropped object', '50']], [1.6, 4.4, 1.6], fs=17))
    b.append(TBL('sd_dir', 'Sample directory entries', ['Name', 'Category', 'Phone', 'Latitude, longitude'], [
        ['Rescue 1122', 'Emergency number', '1122', '-'], ['Police', 'Emergency number', '15', '-'], ['General Hospital (test)', 'Hospital', '+92 51 0000000', '33.6900, 73.0500'], ['Police Station (test)', 'Police station', '+92 51 0000001', '33.6850, 73.0450']], [2.2, 1.6, 1.6, 2.2], fs=17))
    b.append(H1('Document Status', 'status', numbered=False))
    b.append(P('This document is the Software Requirements Specification and Software Design Specification of Muhaffiz. It specifies what the system shall do and how it is designed. The chapters on implementation and testing describe the system as designed and as planned for verification. They are written in the present tense so that the document reads as one description of the system; they do not report results.', indent=True))
    b.append(P('Readers should note the following. The sections on algorithms, interfaces, deployment and the user interface describe the intended realization of the design. The screens in Sections {sec:hmi} and {sec:implui} are renderings of the committed interface design and not screenshots of a running application. The test cases of Chapter 6 are complete, but their Actual Result, Observed Result and Result columns show a hyphen, the executed, passed, failed and blocked counts are zero, and the defect log is empty, because no test has been executed and no result is claimed. The status columns of the milestone plan and of the traceability matrix state the planned or empty status and do not claim that any requirement has been implemented or verified. The survey percentages quoted in this document are percentages of the 73 respondents. The interview evidence consists of four interviews.', indent=True))
    b.append(P('Quantities stated as targets, thresholds or limits, for example in the non-functional requirements and the algorithm parameters, are requirements or default design values and not measured results. Items that depend on outside confirmation are listed in Appendix C.', indent=True))
    return b
